import json,subprocess,time
from pathlib import Path
session='asset-ui-states';logs=[];checks={};out=Path(__file__).resolve().parents[2]/'experiments/04-ui-implementation'
def cli(*args):
 p=subprocess.run(['agent-browser','--session',session,*args],text=True,capture_output=True);logs.append({'argv':args,'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr});assert p.returncode==0,p.stderr;return p.stdout
def ev(s):return json.loads(cli('eval',s))
def wait(s):
 for _ in range(90):
  if ev(s):return
  time.sleep(.12)
 raise AssertionError(s)
def send(s):
 cli('fill','textarea',s);cli('click','button[aria-label="Send message"]')
def check(label,fn):
 try:fn();checks[label]={'passed':True}
 except Exception as e:checks[label]={'passed':False,'error':str(e)}
def error_retry():
 send('simulate error');wait("document.querySelectorAll('.response-error').length===1");wait("!document.querySelector('button[aria-label=\"Stop response\"]')");cli('eval',"document.querySelector('.response-error button').click();void 0");wait("document.querySelectorAll('.response-error').length===1 && !document.querySelector('button[aria-label=\"Stop response\"]')");assert ev("document.querySelectorAll('.chat-message.user').length===1")
 cli('open','http://localhost:5190');wait("document.querySelectorAll('.response-error').length===1");assert ev("document.querySelectorAll('.chat-message.user').length===1 && document.querySelectorAll('.chat-message.assistant').length===1"),'retry duplicated turn';assert ev("!document.querySelector('.assistant-heading').textContent.includes('Evidence-backed answer')");cli('screenshot',str(out/'error-state.png'))
def empty():
 cli('click','.new-conversation');send('Show empty sample fleet overview');wait("document.querySelectorAll('.answer-empty').length===1");wait("!document.querySelector('button[aria-label=\"Stop response\"]')");assert ev("document.querySelectorAll('.answer-empty').length===1 && document.querySelectorAll('[data-panel]').length===0");assert ev("!document.querySelector('.answer-narrative').textContent.includes('Two sample assets')");cli('screenshot',str(out/'empty-state.png'))
def stop():
 cli('click','.new-conversation');send('Show a sample fleet overview');wait("!!document.querySelector('button[aria-label=\"Stop response\"]')");cli('click','button[aria-label="Stop response"]');wait("!!document.querySelector('.response-error')");time.sleep(1.3);assert ev("document.querySelectorAll('[data-panel]').length===0")
def bar():
 cli('click','.new-conversation');send('Show bar sample');wait("!!document.querySelector('[data-panel=bar] .analytics-chart svg')");wait("!document.querySelector('button[aria-label=\"Stop response\"]')");assert ev("!document.querySelector('[data-panel=bar]').textContent.includes('This view is unavailable')")
def partial_records():
 cli('eval',"const key='asset-intelligence.sessions.v1';const sessions=JSON.parse(localStorage.getItem(key));const id=document.querySelector('[data-session-id]').dataset.sessionId;const m=sessions.find(s=>s.id===id).messages.filter(m=>m.role==='assistant').at(-1);m.status='partial';m.answer.generation={status:'partial',verified_tool_data:true,explanation_error_code:'provider_rate_limited'};m.retryAt=new Date(Date.now()+8000).toISOString();m.text=m.answer.narrative='Recorded partial fixture: source records are available; explanation is incomplete.';localStorage.setItem(key,JSON.stringify(sessions));void 0");cli('reload');wait("!!document.querySelector('.partial-result-notice')");wait("document.querySelectorAll('[data-panel]').length>0");assert ev("document.querySelectorAll('[data-panel]').length>0 && !document.querySelector('.assistant-heading').textContent.includes('Evidence-backed')"),'partial panels/header';assert ev("document.querySelector('.partial-result-notice button').disabled"),'server cooldown disabled';time.sleep(8.2);wait("!document.querySelector('.partial-result-notice button').disabled");cli('click','.partial-result-notice button');wait("!document.querySelector('button[aria-label=\"Stop response\"]') && !document.querySelector('.partial-result-notice')");assert ev("document.querySelectorAll('.chat-message.user').length===1 && document.querySelectorAll('.chat-message.assistant').length===1"),'retry duplicated turn'
def text_and_evidence_only():
 # Replay validated stored fixture envelopes; no provider request or greeting stub.
 cli('eval',"const key='asset-intelligence.sessions.v1';const sessions=JSON.parse(localStorage.getItem(key));const active=document.querySelector('[data-session-id]').dataset.sessionId;const message=sessions.find(s=>s.id===active).messages.filter(m=>m.role==='assistant').at(-1);message.status='complete';message.answer.generation=undefined;message.retryAt=undefined;message.answer.blocks=[];message.answer.results={};message.text=message.answer.narrative='This is a recorded sample response with evidence only.';localStorage.setItem(key,JSON.stringify(sessions));void 0");cli('open','http://localhost:5190');wait("!!document.querySelector('.evidence-only button')");assert ev("document.querySelectorAll('[data-panel]').length===0");cli('click','.evidence-only button');wait("!!document.querySelector('.ant-drawer-open')");assert ev("document.querySelector('.ant-drawer-open').textContent.includes('Sample weekly inspection')");cli('press','Escape')
 cli('eval',"const key='asset-intelligence.sessions.v1';const sessions=JSON.parse(localStorage.getItem(key));const active=document.querySelector('[data-session-id]').dataset.sessionId;const message=sessions.find(s=>s.id===active).messages.filter(m=>m.role==='assistant').at(-1);message.answer.evidence={};message.text=message.answer.narrative='This recorded sample response contains text only.';localStorage.setItem(key,JSON.stringify(sessions));void 0");cli('open','http://localhost:5190');wait("document.querySelector('.answer-narrative')?.textContent.includes('text only')");assert ev("document.querySelectorAll('[data-panel],.evidence-only,.answer-dashboard').length===0");assert ev("!document.querySelector('.assistant-heading').textContent.includes('Evidence-backed') && document.querySelector('.message-actions').textContent.includes('Response complete')")
cli('open','http://localhost:5190');cli('eval',"Object.keys(localStorage).filter(k=>k.startsWith('asset-intelligence')).forEach(k=>localStorage.removeItem(k));void 0");cli('open','http://localhost:5190');cli('set','viewport','1440','1000');cli('set','media','light');wait("!!document.querySelector('.welcome')");wait("!document.querySelector('.suggestion-card').disabled")
for label,fn in [('error_retry_without_duplicate_user',error_retry),('honest_empty_results',empty),('explicit_stop_no_late_facts',stop),('bar_chart_renderer',bar),('recorded_partial_data_cooldown_retry',partial_records),('recorded_text_and_evidence_only',text_and_evidence_only)]:check(label,fn)
(out/'ui-state-results.json').write_text(json.dumps({'checks':checks,'commands':logs},indent=2)+'\n');print(json.dumps(checks,indent=2))
